INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('640', 'Arrête-moi si tu peux', 'Arrête-moi si tu peux', '2002', 'Dans les années soixante, le jeune Frank Abagnale Jr. est passé maître dans l’art de l’escroquerie, allant jusqu’à détourner 2,5 millions de dollars et à figurer sur les listes du FBI comme l’un des dix individus les plus recherchés des États‐Unis. Véritable caméléon, Frank revêt des identités aussi diverses que celles de pilote de ligne, de médecin, de professeur d’université ou encore d’assistant du procureur. Carl Hanratty, agent du FBI à l’apparence stricte, fait de la traque de Frank Abagnale Jr. sa mission prioritaire, mais ce dernier reste pendant longtemps insaisissable…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('597', 'Titanic', 'Titanic', '1997', 'Southampton, 10 avril 1912. Le paquebot le plus grand et le plus moderne du monde, réputé pour son insubmersibilité, le « Titanic », appareille pour son premier voyage. Quatre jours plus tard, il heurte un iceberg. À son bord, un artiste pauvre et une grande bourgeoise tombent amoureux.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('106646', 'Le Loup de Wall Street', 'Le Loup de Wall Street', '2013', 'Sa licence de courtier en poche, et les narines déjà pleines de cocaïne, Jordan Belfort est prêt à conquérir Wall Street. Ce jour d''octobre, un krach, le plus important depuis 1929, vient piétiner ses rêves de grandeur. C''est finalement à Long Island qu''il échoue et qu''il monte sa propre affaire de courtage. Son créneau : le hors-cote. Sa méthode : l''arnaque. Son équipe : des vendeurs ou des petits trafiquants.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('27205', 'Inception', 'Inception', '2010', 'Dom Cobb est un voleur expérimenté, le meilleur dans l''art dangereux de l''extraction, voler les secrets les plus intimes enfouis au plus profond du subconscient durant une phase de rêve, lorsque l''esprit est le plus vulnérable. Les capacités de Cobb ont fait des envieux dans le monde tourmenté de l''espionnage industriel alors qu''il devient fugitif en perdant tout ce qu''il a un jour aimé. Une chance de se racheter lui est alors offerte. Une ultime mission grâce à laquelle il pourrait retrouver sa vie passée mais uniquement s''il parvient à accomplir l''impossible inception.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('64682', 'Gatsby le Magnifique', 'Gatsby le Magnifique', '2013', 'Printemps 1922. L''époque est propice au relâchement des mœurs, à l''essor du jazz et à l’enrichissement des contrebandiers d’alcool… Apprenti écrivain, Nick Carraway quitte la région du Middle‐West pour s''installer à New York. Voulant sa part du rêve américain, il vit désormais entouré d''un mystérieux millionnaire, Jay Gatsby, qui s''étourdit en fêtes mondaines, et de sa cousine Daisy et de son mari volage, Tom Buchanan, issu de sang noble. C’est ainsi que Nick se retrouve au cœur du monde fascinant des milliardaires, de leurs illusions, de leurs amours et de leurs mensonges. Témoin privilégié de son temps, il se met à écrire une histoire où se mêlent des amours impossibles, des rêves d’absolu et des tragédies ravageuses et, chemin faisant, nous tend un miroir où se reflètent notre époque moderne et ses combats.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('11324', 'Shutter Island', 'Shutter Island', '2010', 'En 1954, le marshal Teddy Daniels et son coéquipier Chuck Aule sont envoyés enquêter sur l’île de Shutter Island, dans un hôpital psychiatrique où sont internés de dangereux criminels. L’une des patientes, Rachel Solando, a inexplicablement disparu. Comment la meurtrière a‐t‐elle pu sortir d’une cellule fermée de l’extérieur ? Le seul indice retrouvé dans la pièce est une feuille de papier sur laquelle on peut lire une suite de chiffres et de lettres sans signification apparente. Œuvre cohérente d’une malade, ou cryptogramme ?', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('68718', 'Django Unchained', 'Django Unchained', '2012', 'Dans le sud des États‐Unis, deux ans avant la guerre de Sécession, le Dr King Schultz, un chasseur de primes allemand, fait l’acquisition de Django, un esclave qui peut l’aider à traquer les frères Brittle, les meurtriers qu’il recherche. Schultz promet à Django de lui rendre sa liberté lorsqu’il aura capturé les Brittle – morts ou vifs. Alors que les deux hommes pistent les dangereux criminels, Django n’oublie pas que son seul but est de retrouver Broomhilda, sa femme, dont il fut séparé à cause du commerce des esclaves… Lorsque Django et Schultz arrivent dans l’immense plantation du puissant Calvin Candie, ils éveillent les soupçons de Stephen, un esclave qui sert Candie et a toute sa confiance. Le moindre de leurs mouvements est désormais épié par une dangereuse organisation de plus en plus proche… Si Django et Schultz veulent espérer s’enfuir avec Broomhilda, ils vont devoir choisir entre l’indépendance et la solidarité, entre le sacrifice et la survie…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1907', 'La Plage', 'La Plage', '2000', 'Richard, jeune Américain, amateur de sensations inédites a choisi l''Asie comme terrain d''élection, dans l''espoir d''y vivre des aventures fortes et exaltantes. Dans un hôtel miteux de Bangkok boudé par les touristes, il fait la connaissance d''un couple de Francais, Françoise et Etienne. Dans la nuit, un homme au regard halluciné fait irruption dans sa chambre et évoque une île secrète, une plage paradisiaque, où il aurait vécu plusieurs années au sein d''une petite communauté d''esprits libres. Le lendemain, Richard retrouve une carte de l''île et le cadavre de Daffy.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('680', 'Pulp Fiction', 'Pulp Fiction', '1994', 'L’odyssée sanglante et burlesque de petits malfrats dans la jungle d’Hollywood : Deux petits tueurs, un dangereux gangster marié à une camée, un boxeur roublard, des prêteurs sur gages sadiques, un caïd élégant et dévoué, un dealer bon mari et deux tourtereaux à la gâchette facile.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('500', 'Reservoir Dogs', 'Reservoir Dogs', '1992', 'Après un hold‐up manqué, des cambrioleurs de haut vol font leurs comptes dans une confrontation violente, pour découvrir lequel d’entre eux les a trahis.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('24', 'Kill Bill : Volume 1', 'Kill Bill : Volume 1', '2003', 'Au cours d''un mariage, un commando armé massacre l''assistance, laissant pour morte la Mariée et l''enfant qu''elle porte. Après 4 ans de coma, la Mariée se lance à la poursuite des assassins, membres du clan de Bill, au sein duquel, sous le pseudonyme de Black Mamba, elle exerça elle-même autrefois ses talents de redoutable tueuse…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('393', 'Kill Bill : Volume 2', 'Kill Bill : Volume 2', '2004', 'Après avoir éliminé ses deux anciennes collègues Vernita Green et O-Ren Ishii, la Mariée, alias Black Mamba, poursuit l''éradication du gang des Vipères Assassines. Prochaines cibles : Budd, puis Elle Driver, avant d''atteindre enfin son but ultime : tuer leur chef, Bill…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('16869', 'Inglourious Basterds', 'Inglourious Basterds', '2009', 'Dans la France occupée de 1940, un groupe de soldats juifs américains, les bâtards, mène des actions punitives particulièrement sanglantes contre les nazis du Troisième Reich. Leur chemin rencontre celui de Shosanna Dreyfus, une jeune juive réfugiée à Paris exploitante d''une salle de cinéma qui entend elle aussi assouvir sa propre vengeance envers les nazis.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('550', 'Fight Club', 'Fight Club', '1999', 'Le narrateur, sans identité précise, vit seul, travaille seul, dort seul, mange seul ses plateaux‐repas pour une personne comme beaucoup d’autres personnes seules qui connaissent la misère humaine, morale et sexuelle. C’est pourquoi il va devenir membre du Fight club, un lieu clandestin où il va pouvoir retrouver sa virilité, l’échange et la communication. Ce club est dirigé par Tyler Durden, une sorte d’anarchiste entre gourou et philosophe qui prêche l’amour de son prochain.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('297', 'Rencontre avec Joe Black', 'Rencontre avec Joe Black', '1998', 'Une nuit, le magnat William Parrish ressent une violente douleur tandis qu''une voix surgissant des ténèbres lui annonce sa mort prochaine. À ce moment-là, un jeune inconnu se présente à son domicile pour l''accompagner vers son dernier voyage. Ce messager de l''au-delà impose à Parrish de l''héberger chez lui afin de lui donner l''occasion de partager un temps les expériences, les joies, les émotions et les drames des vivants, qui semblent lui être étrangers. En l''espace de trois jours, Joe Black révèlera toute la famille Parrish à elle-même.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('807', 'Seven', 'Seven', '1995', 'À New York, un criminel anonyme a décidé de commettre 7 meurtres basés sur les 7 pêchés capitaux énoncés dans la Bible : gourmandise, avarice, paresse, orgueil, luxure, envie et colère. Vieux flic blasé à 7 jours de la retraite, l''inspecteur Somerset mène l''enquête tout en formant son remplaçant, l''ambitieux inspecteur David Mills…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('2649', 'The Game', 'The Game', '1997', 'Nicholas Van Orton, homme d''affaires avisé, reçoit le jour de son anniversaire un étrange cadeau que lui offre son frère Conrad. Il s''agit d''un jeu. Nicholas découvre peu à peu que les enjeux en sont très élevés, bien qu''il ne soit certain ni des règles, ni même de l''objectif réel. Il prend peu à peu conscience qu''il est manipulé jusque dans sa propre maison par des conspirateurs inconnus qui semblent vouloir faire voler sa vie en éclats.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('348', 'Alien, le huitième passager', 'Alien', '1979', 'En 2122, le Nostromo, vaisseau de commerce, fait route vers la Terre avec à son bord un équipage de sept personnes en hibernation et une cargaison de minerais. Il interrompt soudain sa course suite à la réception d’un mystérieux message provenant d’une planète inexplorée. Réveillé par l’ordinateur de bord, l’équipage se rend sur place et découvre les restes d’un gigantesque vaisseau extraterrestre dont le seul passager semble être mort dans d’étranges circonstances…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('98', 'Gladiator', 'Gladiator', '2000', 'Le général romain Maximus est le plus fidèle soutien de l''empereur Marc Aurèle, qu''il a conduit de victoire en victoire avec une bravoure et un dévouement exemplaires. Jaloux du prestige de Maximus, et plus encore de l''amour que lui voue l''empereur, le fils de Marc Aurèle, Commode, s''arroge brutalement le pouvoir, puis ordonne l''arrestation du général et son exécution. Maximus échappe à ses assassins mais ne peut empêcher le massacre de sa famille. Capturé par un marchand d''esclaves, il devient gladiateur et prépare sa vengeance.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('286217', 'Seul sur Mars', 'Seul sur Mars', '2015', 'Au cours d’une mission spatiale habitée sur Mars, et à la suite d’un violent orage, l’astronaute Mark Watney est laissé pour mort et abandonné sur place par son équipage. Mais Watney a survécu et se retrouve seul sur cette planète hostile. Avec de maigres provisions, il ne doit compter que sur son ingéniosité, son bon sens et son intelligence pour survivre et trouver un moyen d’alerter la Terre qu’il est encore vivant. À des millions de kilomètres de là, la NASA et une équipe de scientifiques internationaux travaillent sans relâche pour ramener « le Martien » sur terre, pendant que, en parallèle, ses coéquipiers tentent secrètement d’organiser une audacieuse voire impossible mission de sauvetage.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('274', 'Le Silence des agneaux', 'Le Silence des agneaux', '1991', 'Un psychopathe connu sous le nom de Buffalo Bill sème la terreur dans le Middle West en kidnappant et en assassinant de jeunes femmes. Clarice Starling, une jeune stagiaire du FBI, est chargée d’interroger l’ex‐psychiatre Hannibal Lecter. Psychopathe redoutablement intelligent et porté sur le cannibalisme, Lecter est capable de lui fournir des informations concernant Buffalo Bill ainsi que son portrait psychologique. Mais il n’accepte de l’aider qu’en échange d’informations sur la vie privée de la jeune femme. Entre eux s’établit un lien de fascination et de répulsion.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('4547', 'Panic Room', 'Panic Room', '2002', 'Récemment séparée de son mari, Meg Altman est angoissée à l''idée de devoir élever seule sa fille Sarah. Elle achète une immense et splendide maison dans un quartier huppé à l''Ouest de New York. Son ancien propriétaire, un milliardaire, y a fait construire une pièce de sûreté dans laquelle on peut se réfugier en cas de menace extérieure et rester enfermé de nombreux jours grâce aux provisions qu''elle contient. Un soir, trois cambrioleurs pénètrent dans la maison avec la ferme intention de dérober une somme de 14 millions de dollars cachée par l''ancien maître des lieux. Ce butin serait-il dissimulé dans la pièce de sûreté, là où se sont réfugiées Meg et Sarah ?', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('629', 'Usual Suspects', 'Usual Suspects', '1995', 'Suspect numéro 1 dans une étrange affaire de hold-up, Verbal Kint est soumis à un interrogatoire par des agents fédéraux. Très vite, il dévoile aux policiers que le véritable cerveau de cette affaire n''est autre que le redoutable criminel Keyser Soze, un être machiavélique possédant une intelligence hors du commun. Peu à peu, le suspect va dresser un portrait effrayant de ce criminel que personne n''a jamais vu…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('161', 'Ocean''s Eleven', 'Ocean''s Eleven', '2001', 'À peine sorti de prison, Danny Ocean n''a qu''une idée en tête : organiser le casse du siècle en cambriolant les trois plus grands casinos de Las Vegas. Pour cela il réunit une équipe de malfrats spécialistes dans des domaines aussi variés que les explosifs, l''informatique, le bluff...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('163', 'Ocean''s Twelve', 'Ocean''s Twelve', '2004', 'Trois ans ont passé depuis le braquage historique du casino Bellagio de Las Vegas. Depuis, Danny Ocean et ses associés se sont dispersés dans la nature avec l''intention de mener une existence honnête. Remarié à Tess, ce dernier joue profil bas jusqu''au jour où Terry Benedict retrouve sa trace. Le propriétaire du Bellagio n''y va pas par quatre chemins: la bande doit, sous peine de mort, lui restituer le magot. Et ce n''est qu''un début, car quelqu''un d''autre s''intéresse de très près aux agissements de la bande des Onze...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('298', 'Ocean''s 13', 'Ocean''s Thirteen', '2007', 'Willy Bank n''aurait pas dû s''attaquer à un ami de Danny Ocean... Pour avoir trahi Reuben Tishkoff, Willy Bank, propriétaire sans scrupule d''un casino flambant neuf, va être sévèrement attaqué par toute l''équipe de Danny Ocean. Celle-ci n''aura plus qu''un objectif: infliger à Bank un châtiment exemplaire le soir de l''inauguration de son nouveau casino. Mais cette fois la chance ne leur suffira pas pour faire sauter The Bank...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('954', 'Mission : Impossible', 'Mission : Impossible', '1996', 'Ethan Hunt, un agent secret de haut niveau, est accusé de la mort de son équipe d''espionnage. Alors qu''il fuit les criminels du gouvernement, qu''il s''introduit dans la chambre forte la plus impénétrable de la CIA et qu''il se cramponne au toit d''un train à grande vitesse, Hunt se retrouve dans une course effrénée pour devancer ceux qui le poursuivent… et se rapprocher petit à petit d''une vérité bouleversante.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('74', 'La Guerre des mondes', 'La Guerre des mondes', '2005', 'Ray Ferrier est un docker divorcé et un père rien moins que parfait, qui n’entretient plus que des relations épisodiques avec son fils Robbie, 17 ans, et sa fille Rachel, 11 ans. Quelques minutes après que son ex‐femme et l’époux de cette dernière lui ont confié la garde des enfants, un puissant orage éclate. Ray assiste alors à un spectacle qui bouleversera à jamais sa vie…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('180', 'Minority Report', 'Minority Report', '2002', 'Washington, 2054. Plus aucun meurtre ne se produit grâce au « pré-crime », l’unité policière dirigée par John Anderton. Cette unité dispose d''un système lui permettant de visualiser les meurtres avant qu''ils ne se produisent. Mais quand John découvre qu''il est lui-même accusé d''un meurtre à venir, il n''a que 36 heures pour comprendre le véritable fonctionnement de ce système.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1903', 'Vanilla Sky', 'Vanilla Sky', '2001', 'David Aames est un jeune et brillant éditeur new-yorkais qui a tout pour lui : l''argent, la réussite professionnelle et les femmes. Son ami Pelayo commet l''erreur de lui présenter Sofia, sa nouvelle compagne. Au premier regard, David succombe au charme de celle-ci. Tous les deux filent bientôt le parfait amour. Alors que David se dispute en voiture avec Julie, une ex folle de jalousie, la jeune femme accélère et c''est l''accident. Julie décède. Atrocement défiguré, David est transporté d''urgence à l''hôpital où les médecins ne peuvent réaliser de miracle. Sa vie bascule. Les gens ont dorénavant peur de lui et Sofia l''évite. Mais un matin, David se fait gentiment réveiller par celle-ci, qui lui déclare son amour. Les médecins lui annoncent même qu''il pourra retrouver son ancien visage. Réalité ou hallucination ?', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('334', 'Magnolia', 'Magnolia', '1999', 'Earl Partridge, âgé et malade, va bientôt mourir. Il demande à son fidèle infirmier de retrouver le fils qu''il a jadis abandonné. Sa jeune épouse, qui convoitait sa fortune, devrait se réjouir mais n''y parvient pas. Frank Mackey, jeune gourou cathodique de la séduction masculine, s''est construit un passé et une vie. Mais combien de temps le masque peut-il résister ? Toutes ces vies s''entrecroisent le temps d''une journée comme les autres sous le soleil de la Californie.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('881', 'Des hommes d''honneur', 'Des hommes d''honneur', '1992', 'Deux jeunes marines, Louden et Dawson, abattent, au cours d''une action disciplinaire désignée "Code Rouge", un de leur leurs camarades, Santiago. C''est le lieutenant Daniel Kaffee qui est désigné pour assurer leur défense lors de leur procès. Mais si Kaffee entame une défense de pure routine, sa jeune et pugnace adjointe, le lieutenant JoAnne Galoway, se rebiffe et l''oblige a instruire le dossier. Kaffee va devoir, pour découvrir la vérité sur cette affaire qui s''avère inquiétante, remonter jusqu''au sommet de la hiérarchie.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('37233', 'La Firme', 'La Firme', '1993', 'À la fin de ses études de droit, Mitch McDeere, brillant élément, est sollicité par plusieurs grands cabinets d''avocats. Il fixe son choix sur Bendini, Lambert & Locke, qui lui offrent les conditions les plus avantageuses. En contrepartie, il devra, comme chaque membre du cabinet, fournir quelque quatre-vingts heures de travail hebdomadaire. Il ignore encore qu''il vient de vendre son âme au diable.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('544', 'Mary à tout prix', 'Mary à tout prix', '1998', 'Ted, le loser, décide de retrouver son amour de jeunesse, la splendide Mary. Il engage un détective privé, Pat Healy, pour la retrouver. Persuadé qu''il a affaire à un dégénéré, Healy file à Miami et retrouve Mary. Elle est belle, gentille, s''occupe d''enfants handicapés et elle est célibataire. Decidé à garder Mary pour lui, il raconte à Ted qu''elle est devenue grosse, qu''elle est paralytique et qu''elle a quatre enfants. Mais Tucker, un architecte, est également amoureux de Mary. Il va faire cause commune avec Healy pour se débarrasser de Ted qui finalement a décidé de venir à Miami.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1593', 'La Nuit au musée', 'La Nuit au musée', '2006', 'Le Muséum d''Histoire Naturelle renferme dans ses murs un secret mystérieux et stupéfiant que Larry, nouveau gardien de sécurité, ne va pas tarder à découvrir avec affolement : la nuit, toutes les expositions prennent vie ! Sous ses yeux, les soldats romains et les cow-boys miniatures se lancent dans une guerre acharnée, Attila et ses Huns commencent à piller les expositions avoisinantes, la momie tente de sortir de son sarcophage, le squelette du redoutable – mais néanmoins attachant – tyrannosaure rôde dans les couloirs... Le chaos est total ! Larry pourra-t-il remettre de l''ordre dans ses collections et sauver le musée ?', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1597', 'Mon beau-père et moi', 'Mon beau-père et moi', '2000', 'Greg Focker, un modeste infirmier de Chicago, vit depuis deux mois avec la charmante Pam Byrnes et rêve d''officialiser leur union. Ravie de sa proposition, la jeune femme insiste pour un strict respect des règles bourgeoises : Greg devra obtenir l''accord de son père, Jack.Deux semaines plus tard, le couple fait son apparition dans la luxueuse résidence des Byrnes. Accueilli à bras ouverts par la mère de Pam, Dina, Greg décèle d''emblée une certaine froideur chez Jack. Ce dernier ne compte pas "céder" sa fille chérie au premier venu.Bien décidé à emporter la mise, Greg, nerveux, se met en quatre pour s''attirer la sympathie et le respect de son beau-père, ancien agent de la CIA, mais toutes ses amabilités, toutes ses plaisanteries tombent à plat face à cet homme crispé, possessif et paranoïaque.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('693', 'Mon beau-père, mes parents et moi', 'Mon beau-père, mes parents et moi', '2004', 'Greg Focker est un brave infirmier qui accumule les déboires, les maladresses et les faux-pas. Soucieux de plaire à tout le monde et de faire oublier son nom grotesque, sa première entrevue avec ses futurs beaux-parents Jack et Dina Byrnes fut un concentré exemplaire de tout ce qu''il ne faut pas faire dans de telles circonstances. Entre-temps, les choses se sont arrangées, et Greg a même réussi à amadouer le terrifiant Jack et à intégrer son cercle de confiance. Pam et lui peuvent donc envisager le mariage, mais il reste à organiser une réunion entre les Byrnes et les Focker. Un paisible week-end en Floride dans la propriété de Bernie et Roz Focker - lui fervent libéral, elle sexologue militante - permettra enfin aux deux familles de lier connaissance. Un ultime examen de passage, qui ne devrait pas poser de problème…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('90', 'Le Flic de Beverly Hills', 'Le Flic de Beverly Hills', '1984', 'Axel Foley, ancien voyou, est maintenant un des flics les plus efficaces de Detroit. Et même si ses méthodes sont loin d''être traditionnelles, ses supérieurs sont bien obligés de reconnaître ses qualités. Axel retrouve un ami d’enfance, mais celui-ci est assassiné le jour de leurs retrouvailles. L''enquête lui étant refusée, Axel prend ses congés et se lance à la poursuite du meurtrier. Le petit flic de Detroit se retrouve à Beverly Hills, entraîné dans le milieu des dealers et des truands…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('9602', 'Un prince à New York', 'Un prince à New York', '1988', 'Au royaume africain du Zamunda, son altesse royale, le prince Akeem célèbre ses 21 ans, devant ainsi majeur et doit se marier. Depuis son plus jeune âge, des servantes toutes dévouées ont toujours satisfait le moindre de ses désirs, même les plus intimes et parfait à son éducations royale. Ses parents, le roi Jaffe Joffer et la reine Aoleon, lui ont choisi une future épouse, Imani Izzi, qui n''a été élevée que pour servir le futur roi. Toutefois, le futur roi ne veut pas d''une femme dévouée à sa vie, il souhaite rencontrer une femme en accord avec ses sentiments, avec une personnalité. Pour se faire, et en dissimulant une partie de la vérité à ses royaux parents, Akeem gagne New York, dans le quartier du Queens avec son serviteur Semmi où il entreprend de vivre dans une pauvreté factice pour trouver la femme idéale.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1621', 'Un fauteuil pour deux', 'Un fauteuil pour deux', '1983', 'D''un côté, Louis Winthorpe III, un jeune directeur, est chargé des investissements chez Duke & Duke, une puissante banque de Philadelphie. De l''autre, Billy Ray Valentine est un noir combinard mais fauché. Tous deux vont faire l''objet d''un pari insensé, passé entre les patrons de Louis.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('105', 'Retour vers le futur', 'Retour vers le futur', '1985', 'En 1985, Marty, un adolescent comme les autres, mène une existence morne et ennuyeuse. Heureusement, il est épris de la jolie Jennifer et entretient une profonde amitié avec Doc, un savant fou qui prétend avoir inventé une machine à explorer le temps. Un jour, Doc invite Marty à l''essayer…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('771', 'Maman, j''ai raté l''avion !', 'Maman, j''ai raté l''avion', '1990', 'La famille McCallister a décidé de passer les fêtes de Noël à Paris. Seulement Kate et Peter McCallister s''aperçoivent dans l''avion qu''il leur manque le plus jeune de leurs enfants, Kevin, âgé de 9 ans. D''abord désespéré, Kevin reprend vite les choses en main et s''organise pour vivre le mieux possible. Quand deux cambrioleurs choisissent sa maison pour commettre leurs méfaits.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('772', 'Maman, j''ai encore raté l''avion !', 'Maman, j''ai encore raté l''avion', '1992', 'Après Paris, c''est à Miami que la tribu McCallister décide de passer les fêtes de Noël. À l''aube du jour J, toute la famille est sur le pied de guerre et file a l''aéroport en prenant bien garde de ne pas oublier Kevin. Mais celui-ci s''éclipse pour acheter des piles pour son walkman, il ne retrouve plus les siens et s''embarque par mégarde pour New York...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('639', 'Quand Harry rencontre Sally…', 'Quand Harry rencontre Sally', '1989', 'Lorsqu''ils se rencontrent pour la première fois dans les années 70, Harry et Sally ne s''apprécient pas, mais alors pas du tout. Ils se quittent, jurant de ne plus se revoir. Cinq ans plus tard, ils se retrouvent mais rien n''a changé : leurs avis sur les relations hommes-femmes divergent du tout au tout. Cinq autres années passent, et Harry rencontre Sally à nouveau. Ils se racontent leurs expériences, leurs déceptions et se rendent compte que leur vie amoureuse est un désastre. Mais l''amitié entre Harry et Sally est-elle possible ?', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('858', 'Nuits Blanches à Seattle', 'Nuits blanches à Seattle', '1993', 'Annie Reed, journaliste, s''émeut quand elle entend à la radio l''histoire de Sam Baldwin. Touchée par cette histoire, elle tente d''entrer en contact avec Sam, malgré l''approche de son mariage avec Walter et la distance qui sépare Seattle de Baltimore. C''est le début d''une course à l''amour.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('9489', 'Vous avez un mess@ge', 'Vous avez un message', '1998', 'Tous les deux sont libraires. Kathleen tient une échoppe au charme suranné, The Shop Around the Corner, et a initié aux joies de la lecture des ribambelles d''enfants tandis que Joe possède une chaîne de librairies de grande surface, Fox Books, qui a rapidement éliminé ses concurrentes. Kathleen hait plus que tout au monde Fox Books tandis que Joe attend nonchalamment de rayer des librairies celle de Kathlen. Ils ne se connaissent pas mais se croisent tous les jours et surtout comme dans le film de Lubitsch échangent une correspondance follement amoureuse par le biais d''Internet.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('594', 'Le Terminal', 'Le Terminal', '2004', 'Viktor Navorski est l’un de ces milliers de touristes, venus des quatre coins du monde, qui débarquent chaque jour à l’Aéroport JFK de New York. Mais, à quelques heures de son arrivée, voilà qu’un coup d’État bouleverse sa petite république d’Europe Centrale, mettant celle‐ci au ban des nations et faisant de Viktor… un apatride. Les portes de l’Amérique se ferment devant lui, alors même que se bouclent les frontières de son pays: Viktor est bel et bien coincé…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('8358', 'Seul au monde', 'Seul au monde', '2000', 'Chuck Noland, gestionnaire au service d’un transporteur international, ne vit que par son travail. Il sillonne le monde pour améliorer les performances de son entreprise et la productivité de ses équipes. Il ne voit sa compagne Kelly que quelques jours par an. Lors de l’un de ses déplacements, Chuck est victime d’un accident d''avion qui coule en plein Pacifique. Agrippé à un radeau de sauvetage, Chuck s’échoue sur un îlot désert. Seul au monde, privé de tous ses repères habituels, le naufragé doit apprendre les gestes élémentaires pour sa survie.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('497', 'La Ligne verte', 'La Ligne verte', '1999', 'Paul Edgecomb, pensionnaire centenaire d’une maison de retraite, est hanté par ses souvenirs. Gardien-chef du pénitencier de Cold Mountain en 1935, il était chargé de veiller au bon déroulement des exécutions des peines capitales, en s’efforçant d’adoucir les derniers moments des condamnés. Parmi eux, se trouvait un colosse du nom de John Coffey, accusé du viol et du meurtre de deux fillettes. Intrigué par cet homme candide et timide, aux dons magiques, Edgecomb va tisser avec lui des liens très forts.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('13', 'Forrest Gump', 'Forrest Gump', '1994', 'À Savannah, État de Géorgie, Forrest Gump, assis sur un banc public, livre à qui veut l’entendre, l’étrange récit de sa vie mouvementée sur trois décennies. Il naît dans un bourg de l’Alabama, affecté d’un quotient intellectuel inférieur à la moyenne et d’une paralysie partielle des jambes. Souvent raillé à l’école, le jeune Forrest se lie d’amitié avec Jenny. Propulsé de l''état d''handicapé physique à celui de vedette du football, de héros du Vietnam au roi de la crevette, des honneurs de la Maison Blanche au bonheur d''une histoire d''amour, Forrest est le symbole d''une époque, un candide dans une Amérique qui a perdu son innocence.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('9800', 'Philadelphia', 'Philadelphia', '1993', 'Andrew Beckett, brillant avocat, est appelé à une carriere fulgurante. Adulé par son milieu, rien ne semble pouvoir ralentir son ascension. Mais, le jour où ses associés apprennent qu''Andrew est atteint du sida, ils n''hésitent pas à pretexter une faute professionnelle pour justifier son renvoi. Andrew décide de ne pas se laisser faire et attaque le cabinet pour licenciement abusif.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('857', 'Il faut sauver le soldat Ryan', 'Il faut sauver le soldat Ryan', '1998', 'Vue à travers le regard d’une escouade de soldats américains, l’histoire débute le jour du Débarquement au cours de la 2ème Guerre Mondiale, le long des plages de Normandie. Le capitaine John Miller a pour mission de retrouver le soldat James Ryan, dont les trois frères sont morts au combat et il s’expose ainsi à de nombreux risques. Confrontés à une situation périlleuse, les hommes discutent les ordres. Pourquoi huit hommes risqueraient-ils leur vie pour un seul homme ? Rattrapés par la brutalité de la guerre, chacun cherche sa propre réponse ainsi que la force de vaincre un futur incertain avec honneur, décence et courage.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('568', 'Apollo 13', 'Apollo 13', '1995', 'Après les premiers pas de l''homme sur la Lune, la NASA décide de poursuivre les vols habités. Jim Lovell qui, deux ans plus tôt, avait participé au vol Apollo 8, est choisi pour diriger la mission Apollo 13. Avec Fred Haise et Ken Mattingly, il suit un entraînement intensif. Une semaine avant le départ prévu, les médecins détectent chez Ken Mattingly des signes de rougeole. À contrecœur, Jim Lovell doit se résigner à le remplacer par Jack Swigert, insuffisamment préparé à son goût. Le jour du lancement, le 11 avril 1970, Apollo 13 décolle de Cap Kennedy, dans l''indifférence générale. Jusqu''au troisième jour, tout se passe bien…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('1213', 'Le Talentueux M. Ripley', 'Le Talentueux Mr Ripley', '1999', 'Tom Ripley, jeune homme désargenté mais ambitieux, attire l’attention d’un riche vieillard, Herbert Greenleaf, qui le charge de convaincre son fils Dickie, exilé en Italie, de rentrer aux États‐Unis. Sur place, Tom se laisse fasciner par l’existence insouciante et dorée que mène le jeune oisif. Il adopte ses goûts, imite son comportement, désire sa compagne, et va jusqu’à s’éprendre de Dickie lui‐même. Celui‐ci, dans un premier temps, traite Tom comme un ami mais, très vite, il commence à le trouver encombrant, pour ne pas dire énervant. Un jour, alors qu’ils sont seuls en mer, Tom avoue son amour à Dickie, qui le repousse violemment. Le conflit qui s’ensuit se termine par la mort de Dickie…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('22954', 'Invictus', 'Invictus', '2009', 'En 1994, l''élection de Nelson Mandela consacre la fin de l''Apartheid, mais l''Afrique du Sud reste une nation profondément divisée sur le plan racial et économique. Pour unifier le pays et donner à chaque citoyen un motif de fierté, Mandela mise sur le sport, et fait cause commune avec le capitaine de la modeste équipe de rugby sud-africaine. Leur pari: se présenter à la coupe du monde de rugby de 1995...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('2501', 'La Mémoire dans la peau', 'La Mémoire dans la peau', '2002', 'Un homme entre la vie et la mort est tiré de l’océan par un bateau de pêche italien. Ayant retrouvé ses esprits, il se rend compte qu’il souffre d’amnésie totale et qu’il n’a sur lui aucun papier d’identité. Les nombreux talents qu’il se découvre, techniques de combat et connaissances de plusieurs langues, lui suggèrent un passé dangereux. Aidé de la d’abord récalcitrante Marie, il s’engage dans une recherche désespérée pour retrouver son identité et la raison qui pousse d’impitoyables assassins à le traquer.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('70', 'Million Dollar Baby', 'Million Dollar Baby', '2004', 'Rejeté depuis longtemps par sa fille, l’entraîneur Frankie Dunn s’est replié sur lui‐même et vit dans un désert affectif, en évitant toute relation qui pourrait accroître sa douleur et sa culpabilité. Le jour où Maggie Fitzgerald, 31 ans, pousse la porte de son gymnase à la recherche d’un coach, elle n’amène pas seulement avec elle sa jeunesse et sa force, mais aussi une histoire jalonnée d’épreuves et une exigence, vitale et urgente : monter sur le ring, entraînée par Frankie, et enfin concrétiser le rêve d’une vie. Après avoir repoussé plusieurs fois sa demande, Frankie se laisse convaincre par l’inflexible détermination de la jeune femme. Une relation mouvementée, tour à tour stimulante et exaspérante, se noue entre eux, au fil de laquelle Maggie et l’entraîneur se découvrent une communauté d’esprit et une complicité inattendues…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('688', 'Sur la route de Madison', 'Sur la route de Madison', '1995', 'À la mort de leur mère, Michael Johnson et sa sœur Caroline se retrouvent dans la ferme où ils ont passé leur enfance, dans l''Iowa. Ils apprennent avec consternation que la défunte, Francesca, a demandé que ses cendres soient répandues du haut du pont de Roseman. Une bizarrerie que la lecture du journal intime de Francesca va expliquer. Jadis, au cours de l''été 1965, alors que son mari et ses deux enfants s''absentent pour quelques jours, Francesca voit arriver une camionnette bringuebalante. Robert Kincaid, un photographe sexagénaire, en descend et lui demande le chemin du pont de Roseman. Plutôt que de le lui expliquer, Francesca décide de lui montrer le chemin...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('13223', 'Gran Torino', 'Gran Torino', '2008', 'Walt Kowalski est un ancien de la guerre de Corée, un homme inflexible, amer et pétri de préjugés surannés. Après des années de travail à la chaîne, il vit replié sur lui-même, occupant ses journées à bricoler, traînasser et siroter des bières. Avant de mourir, sa femme exprima le vœu qu''il aille à confesse, mais Walt n''a rien à avouer, ni personne à qui parler. Hormis sa chienne Daisy, il ne fait confiance qu''à son M-1, toujours propre, toujours prêt à l''usage… Ses anciens voisins ont déménagé ou sont morts depuis longtemps. Son quartier est aujourd''hui peuplé d''immigrants asiatiques qu''il méprise, et Walt ressasse ses haines, innombrables - à l''encontre de ses voisins, des ados Hmong, latinos et afro-américains « qui croient faire la loi », de ses propres enfants, devenus pour lui des étrangers. Walt tue le temps comme il peut, en attendant le grand départ, jusqu''au jour où un ado Hmong du quartier tente de lui voler sa précieuse Ford Gran Torino…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('190859', 'American Sniper', 'American Sniper', '2014', 'Tireur d’élite des Navy SEAL, Chris Kyle est envoyé en Irak dans un seul but : protéger ses camarades. Sa précision chirurgicale sauve d’innombrables vies humaines sur le champ de bataille et, tandis que les récits de ses exploits se multiplient, il décroche le surnom de « La Légende ». Cependant, sa réputation se propage au-delà des lignes ennemies, si bien que sa tête est mise à prix et qu’il devient une cible privilégiée des insurgés. Malgré le danger, et l’angoisse dans laquelle vit sa famille, Chris participe à quatre batailles décisives parmi les plus terribles de la guerre en Irak, s’imposant ainsi comme l’incarnation vivante de la devise des SEAL : « Pas de quartier ! ». Mais en rentrant au pays, Chris prend conscience qu’il ne parvient pas à retrouver une vie normale.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('278', 'Les Évadés', 'Les Évadés', '1994', 'En 1947, Andy Dufresne, un jeune banquier, est condamné à la prison à vie pour le meurtre de sa femme et de son amant. Ayant beau clamer son innocence, il est emprisonné à Shawshank, le pénitencier le plus sévère de l''État du Maine. Il y fait la rencontre de Red, un noir désabusé, détenu depuis vingt ans. Commence alors une grande histoire d''amitié entre les deux hommes…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('85', 'Les Aventuriers de l''arche perdue', 'Les Aventuriers de l''arche perdue', '1981', 'L''Arche d''Alliance contenant les tables de la Loi brisées par Moïse, voici 3.000 ans, est l''objet de la convoitise des nazis. L''archéologue aventurier Indiana Jones se lance à sa recherche, poursuivi par son ennemi Belloq.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('207', 'Le Cercle des poètes disparus', 'Le Cercle des poètes disparus', '1989', 'Todd Anderson est un garçon plutôt timide. Désormais élève de la prestigieuse académie Welton, réputée pour être l''une des plus fermées et austères des États-Unis, tout le monde attend de lui qu''il suive les traces de son frère, qui avait fait à Welton de brillantes études.  C''est là qu''il va faire la rencontre de M. Keating, un professeur de lettres anglaises qui, c''est le moins que l''on puisse dire, sort des sentiers battus. Jour après jour, M. Keating encourage ses élèves à penser par eux-mêmes et à refuser l''ordre établi. Cette rencontre va bouleverser la vie du jeune Todd, mais aussi celle de ses amis.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('101', 'Léon', 'Léon', '1994', 'Léon est un tueur professionnel redoutable et insaisissable. Il vit seul à New York avec sa plante verte et ses habitudes jusqu''au jour où une petite Mathilda de douze ans sonne à sa porte et fait irruption dans sa vie.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('9322', 'Nikita', 'Nikita', '1991', 'Le braquage d''une pharmacie par une bande de junkies en manque de drogue tourne mal : une fusillade cause la mort de plusieurs personnes dont un policier, abattu par la jeune Nikita. Condamnée à la prison à perpétuité, celle-ci fait bientôt la rencontre de Bob, un homme mystérieux qui contraint la jeune femme à travailler secrètement pour le gouvernement. Après quelques rébellions lors d''un entraînement intensif de plusieurs années, Nikita devient un agent hautement qualifié des services secrets, capable désormais selon Bob d''évoluer seule à l''extérieur. Celui-ci espère d''ailleurs s''en assurer lors d''une terrible mise à l''épreuve au cours de laquelle Nikita doit éliminer un pilier de la mafia asiatique au beau milieu d''un restaurant bondé...', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('175', 'Le Grand Bleu', 'Le Grand Bleu', '1988', 'C''est l''histoire de deux apnéistes, Jacques Mayol et Enzo Molinari. Leur aventure commence dans les îles grecques dès les années 50. Gamins, les deux plongeurs se disputent déjà tous les records des profondeurs. Vingt ans plus tard, ils se retrouvent concurrents au même championnat. «Le grand bleu», c''est l''amitié de ces deux hommes, liés définitivement à la mer.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('23830', 'Last Night', 'Last Night', '2011', 'Joanna et Michael vivent à New York. Aucun nuage, aucun doute n’est jamais venu assombrir leur union, jusqu’à ce que chacun d’eux soit tenté, la même nuit… Pendant que Michael est en déplacement professionnel avec Laura, jeune femme aussi attirante qu’énigmatique, Joanna recroise Alex, l’autre grand amour de sa vie. Les 36 heures qui suivent vont obliger chacun à faire des choix…', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('9377', 'La Folle Journée de Ferris Bueller', 'La Folle Journée de Ferris Bueller', '1986', 'Ferris Bueller, un adolescent populaire et charmeur mais aussi cancre invétéré, convainc sa petite amie et son meilleur ami hypocondriaque (dont le père a une Ferrari) de sécher les cours pour aller passer la journée à Chicago. Pendant qu’ils font les 400 coups dans la grande ville, le proviseur et la sœur de Ferris tentent, chacun de leurs côtés, de prouver aux parents que leur fils est un cancre et qu’il a séché.', FALSE);
INSERT INTO films (id, title, fr_title, year, overview, seen) VALUES ('192', 'Le Nom de la rose', 'Le Nom de la rose', '1986', 'En l’an 1327, dans une abbaye bénédictine, des moines disparaissent. Un franciscain, Guillaume de Baskerville, mène l’enquête, aidé du jeune novice Adso von Melk. C’est l’époque où l’Église, en pleine crise, se voit disputer son pouvoir spirituel et temporel. C’est aussi l’apogée de l’Inquisition.', FALSE);
